[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { background-color: color-mix(in srgb, var(--accent) 35%, #fff); color: #172033; }Starting a new session with a structured summary preserves durable context such as the issue, completed actions, and prior resolution state without retaining stale tool observations. Performing new tool calls before responding makes the current external state the only operational data available to the agent, avoiding conflicts with older results and unsupported prior assertions.

[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-yellow) { background-color: color-mix(in srgb, var(--accent) 55%, #000); color: #ffffff; }
