[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { background-color: color-mix(in srgb, var(--accent) 35%, #fff); color: #172033; }Handling routine summarization in the coordinator avoids the latency and token-processing overhead of spawning a synthesis subagent and retransmitting 80K+ tokens that the coordinator already has in context. Subagent spawning can be reserved for tasks that need additional or complex analysis.

[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-yellow) { background-color: color-mix(in srgb, var(--accent) 55%, #000); color: #ffffff; }
