[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { background-color: color-mix(in srgb, var(--accent) 35%, #fff); color: #172033; }Agent outputs are not automatically included in a separate model invocation. The coordinator must provide the previous agents’ findings as input context for the synthesis agent; otherwise, it has no research material to synthesize.

[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-yellow) { background-color: color-mix(in srgb, var(--accent) 55%, #000); color: #ffffff; }
